import {water01Data as data} from './water01-data.js?v=20261028-water01';
import {developmentPaths} from './development-data.js?v=20261026-development01';
import {managementScene} from './model-ecosystems4.js?v=20261024-ecosystems04';
export {water01Data} from './water01-data.js?v=20261028-water01';
export const water01Views={
 'dev-water-distribution':[['stores','Freshwater stores'],['map','Compare five countries'],['recharge','Groundwater recharge'],['boundaries','Internal and external']],
 'dev-water-availability-scales':[['map','Global comparison'],['catchments','Within a country'],['delivery','Source to tap'],['local','Investigate local access']],
 'dev-water-surplus-deficit':[['climate','Inputs and losses'],['storage','Seasonal storage'],['aquifer','Abstraction and recharge'],['balance','Supply versus demand']],
 'dev-water-supply-demand-change':[['history','Since the 1970s'],['interventions','Change accessible supply'],['projection','Population projection'],['pressure','Supply per person']],
 'dev-water-sector-use':[['definitions','What is withdrawn?'],['countries','Compare sector shares'],['amounts','Share versus volume'],['global','Read category definitions']]
};
export const water01Requirements=Object.fromEntries(Object.entries(water01Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const water01Animated=(k,v)=>({'dev-water-distribution':['recharge'],'dev-water-availability-scales':['delivery'],'dev-water-surplus-deficit':['climate','storage','aquifer','balance'],'dev-water-supply-demand-change':['interventions','pressure'],'dev-water-sector-use':[]}[k]||[]).includes(v);
export const waterStore=(start,inflow,use,loss)=>start+inflow-use-loss;
export const waterPerPerson=(supply,people)=>people>0?supply/people:null;
export const waterClass=v=>v<1000?0:v<2000?1:v<10000?2:3;
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const L=(d,c='#b5cdd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const D=(x,y,c='#edb396',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f1e4ce"/>`;
const B=(x,y,w,a,b)=>`<rect x="${x}" y="${y}" width="${w}" height="${b?66:40}" rx="10" fill="#35566b" stroke="#a6c1c8"/>`+T(x+12,y+24,a)+(b?T(x+12,y+47,b,11):'');
const F=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const A=(u,t)=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data geo-water-data"><caption>${cap}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const sources={stores:A('https://www.usgs.gov/water-science-school/science/where-earths-water','USGS freshwater distribution')+'. Historical Shiklomanov 1993 estimate, rounded; percentages of freshwater, not all Earth’s water. Not a 2026 stock survey.',map:A('https://data.worldbank.org/indicator/ER.H2O.INTR.PC','FAO AQUASTAT via WDI, 2022 extract')+' · '+A('https://databank.worldbank.org/metadataglossary/world-development-indicators/series/ER.H2O.INTR.PC','Indicator definition')+' · '+A('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth geometry, public domain')+'. Internal long-term renewable flows divided by population; excludes external inflows. Not observed 2022 rainfall, safe access or a water-stress index. Intermittent estimates/methods limit comparison. WDI CC BY4.0; raw responses retained.',countries:A('https://data.worldbank.org/indicator/ER.H2O.FWAG.ZS?locations=US-IN-ET','FAO/WDI agriculture')+' · '+A('https://data.worldbank.org/indicator/ER.H2O.FWIN.ZS?locations=US-IN-ET','Industry')+' · '+A('https://data.worldbank.org/indicator/ER.H2O.FWDM.ZS?locations=US-IN-ET','Domestic')+'. Matched 2022 extract, displayed to 1 decimal; rounded shares may not sum exactly 100. Country estimates have methodological limits. Withdrawal is not permanent consumption or safe-access coverage. CC BY4.0; raw JSON retained.',global:A('https://unstats.un.org/sdgs/report/2025/Goal-06/','UN SDG2025 report:2022 global withdrawals')+'. Services includes domestic; it is not a household-only category. Shares of freshwater withdrawal, not all water or rainfall.',history:A('https://www.unesco.org/reports/wwdr/en/2024/s','UNESCO 2024 water-demand summary')+'. Dated overview describes demand increasing since the 1980s; not a current forecast or a constant rate for every country/year. The1970s–2020s mechanism timeline is conceptual, not measured annual data.',process:A('https://www.usgs.gov/special-topics/water-science-school/science/water-cycle','USGS water cycle')+' · '+A('https://www.unesco.org/reports/wwdr/en/2024/s','UNESCO water availability')+'. Invented units, placements and timing; not a measured catchment, engineering design, ecological-flow estimate or water forecast. Replay resets only the worked example.'};
const S=k=>`<p class="geo-caption">${sources[k]}</p>`;
export function water01Evidence(k='map'){
 let b='',c='';
 if(k==='projection')return managementScene('eco-population-projections','projection',0)+`<p class="geo-caption">Population evidence only. Future water supply and use intensity need separate assumptions; this is not a water forecast.</p>`;
 if(k==='stores'){b=T(20,30,'WHERE FRESHWATER IS STORED',14)+T(20,55,'Percent of freshwater · rounded historical estimate',11);for(const[i,[n,v]]of data.stores.entries()){const y=105+i*74;b+=T(20,y-20,n,12)+`<rect x="20" y="${y-9}" width="${v*4}" height="28" rx="3" fill="${['#c5d6d5','#adc5b0','#edb396'][i]}"/>`+T(30+v*4,y+11,v+'%',13);}b+=L('M20 312H420')+T(20,333,'0',10)+T(204,333,'50',10)+T(386,333,'100%',10);c='Most freshwater is stored in ice and groundwater. These three categories share a freshwater denominator; the surface/other category includes several small stores.';return F(b,c)+S('stores')+table('USGS rounded freshwater stock estimates',['Store','% freshwater'],data.stores);}
 if(k==='map'){const colors=['#edb396','#d8c9a4','#94b5ad','#c8d7cd'];b=T(20,27,'INTERNAL RENEWABLE WATER / PERSON',13)+T(20,47,'2022 extract · m³/person/year · North ↑',11)+`<rect x="20" y="55" width="400" height="200" fill="#294f65"/>`+developmentPaths.map(p=>{const row=data.resources.find(r=>r.code===p.code);return `<path d="${p.d}" fill="${row?colors[waterClass(row.value)]:'#647a82'}" stroke="#203e53" stroke-width="0.5"/>`;}).join('');for(const[i,label]of ['<1,000','1,000–<2,000','2,000–<10,000','≥10,000'].entries()){const x=20+i*102;b+=`<rect x="${x}" y="268" width="14" height="13" fill="${colors[i]}"/>`+T(x,300,label,10);}b+=T(20,327,'Grey = not selected · 5 countries only · not tap access',11);c='Five-country thematic map using actual generalised country outlines and a dated FAO/WDI internal-resource-per-person join. External flows are excluded: Egypt’s low internal value is not total Nile supply. Grey means not selected, not zero.';return F(b,c)+S('map')+table('2022 WDI internal renewable flows per person (rounded for display)',['Country','m³/person/year'],data.resources.map(r=>[r.name,Math.round(r.value).toLocaleString('en-GB')]));}
 if(k==='countries'){b=T(20,30,'WITHDRAWAL SHARES · MATCHED 2022',13)+T(20,55,'Each country’s own total =100% · rounded',11);const keys=['agriculture','industry','domestic'],colors=['#adc5b0','#edb396','#a9c3cc'];for(const[i,r]of data.sectors.entries()){const y=99+i*68;let x=20;b+=T(20,y-12,r.name,13);for(const[j,key]of keys.entries()){const v=Number(r[key].toFixed(1));b+=`<rect x="${x}" y="${y}" width="${v*4}" height="25" fill="${colors[j]}"/>`;x+=v*4;}b+=T(20,y+44,keys.map(key=>r[key].toFixed(1)).join(' / ')+'%',12);}for(const[i,n]of ['Agriculture','Industry','Domestic'].entries()){const x=20+i*139;b+=`<rect x="${x}" y="305" width="12" height="12" fill="${colors[i]}"/>`+T(x+17,316,n,11);}c='Country sector shares in agriculture / industry / domestic order. Percentages have different national totals; they cannot establish which country withdraws the largest absolute volume.';return F(b,c)+S('countries')+table('FAO/WDI 2022, displayed1decimal',['Country','Agriculture %','Industry %','Domestic %'],data.sectors.map(r=>[r.name,r.agriculture.toFixed(1),r.industry.toFixed(1),r.domestic.toFixed(1)]));}
 if(k==='global'){b=T(20,30,'GLOBAL WITHDRAWALS ·2022',14);for(const[i,[n,v]]of data.globalSectors.entries()){const y=95+i*75;b+=T(20,y-12,n,13)+`<rect x="20" y="${y}" width="${v*4}" height="28" fill="${['#adc5b0','#edb396','#a9c3cc'][i]}"/>`+T(30+v*4,y+20,v+'%',13);}b+=T(20,326,'Services is broader than household-only use.',12);c='Global shares use the source’s services category. Do not rename it as a household-only measure when comparing with another account.';return F(b,c)+S('global')+table('UN 2025 report,2022 global withdrawal shares',['Sector','%'],data.globalSectors);}
 return '';
}
const flow=(x1,y1,x2,y2,t,c='#a9c3cc')=>L(`M${x1} ${y1}L${x2} ${y2}`)+D(x1+(x2-x1)*t,y1+(y2-y1)*t,c);
function ground(t,pump=25,recharge=10){const stock=80+(recharge-pump)*t;return `<path d="M20 130Q90 100 160 130T300 130T420 130V303H20Z" fill="#778e80" stroke="#bdcec1"/><rect x="35" y="${285-stock}" width="290" height="${stock}" fill="#82abb7" opacity="0.9"/><path d="M340 260V100H400" fill="none" stroke="#edb396" stroke-width="6"/>`+flow(125,140,125,210,t)+flow(340,260,340,105,t,'#edb396')+T(20,60,`Recharge ${recharge} · pumping ${pump} units`,13)+T(48,230,'Stored water: '+stock.toFixed(0),15)+T(20,332,'Pores/fractures simplified · not an underground lake',10);}
export function water01Scene(k,v,t=0){if(!water01Views[k])return '';if(!water01Requirements[k].includes(v))v=water01Requirements[k][0];t=water01Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='process';
 if(['stores','map','countries','global','projection'].includes(v))return water01Evidence(v);
 if(k==='dev-water-distribution'){
 if(v==='recharge'){b=T(20,30,'RECHARGE AND ABSTRACTION',14)+ground(t,25,10);c='An invented aquifer loses stored water when pumping exceeds recharge. Moving tokens show transfer direction; the filled band symbolises water in rock pores and fractures, not an underground lake.';}
 else{b=T(20,30,'DRAW THE RESOURCE BOUNDARY',14)+B(20,75,180,'Internal rainfall','Runoff and recharge')+B(240,75,180,'External river inflow','From upstream countries')+B(110,245,220,'Full supply assessment','Flows / quality / access')+L('M110 145L180 235M330 145L260 235')+T(20,323,'Internal resources ≠ total resources ≠ safe tap supply',11);c='A static accounting framework, not a real basin map. Internal and external renewable flows must be defined without double counting; accessibility and quality require separate evidence.';s='map';}
 }
 if(k==='dev-water-availability-scales'){
 if(v==='catchments'){b=T(20,30,'ONE INVENTED COUNTRY · TWO CATCHMENTS',12)+B(20,75,190,'Wet upland','Supply 120 / demand 40')+B(230,75,190,'Drier city','Supply 30 / demand 70')+L('M210 110H228')+T(80,197,'Possible transfer: requires infrastructure',12)+B(20,240,400,'A total can hide a local gap','Not a real country map or transfer scheme');c='Invented usable-supply and demand units for one period after environmental needs. An aggregate surplus does not ensure that the city can obtain water; transfer feasibility and impacts need assessment.';}
 else if(v==='delivery'){b=T(20,30,'FROM SOURCE TO RELIABLE ACCESS',13)+B(20,75,180,'Source','Quantity and quality')+B(240,75,180,'Treatment and storage','Capacity / maintenance')+B(120,245,200,'Users','Pipes / affordability')+flow(200,108,232,108,t)+flow(330,145,255,235,t)+L('M330 180H405')+D(330+75*t,180,'#edb396')+T(20,326,'Side branch = leakage; illustrative, not a measured rate',10);c='Conceptual treatment, storage and delivery chain. A leak diverts some flow; neither a moving token nor a high natural-resource average proves safe, reliable or equitable household access.';}
 else{b=T(20,30,'LOCAL AVAILABILITY CHECK',14)+B(20,70,400,'When and where?','Season / neighbourhood / competing demand')+B(20,165,400,'Can people use it safely?','Water quality / treatment / reliable pipes')+B(20,260,400,'Who can access the service?','Cost / distance / maintenance / inclusion');c='A local enquiry framework. The boxes are factors to investigate, not measured scores or an assumption that national income determines every household’s access.';}
 }
 if(k==='dev-water-surplus-deficit'){
 if(v==='climate'){b=T(20,30,'CLIMATE: INPUTS AND LOSSES',14)+B(20,70,190,'Wetter example','Rain 100 / evaporation 30')+B(230,70,190,'Drier example','Rain 40 / evaporation 35')+flow(70,148,70,250,t)+flow(150,250,150,148,t,'#edb396')+flow(275,148,275,250,t)+flow(355,250,355,148,t,'#edb396')+T(40,269,'Rain ↓   Evaporation ↑',10)+T(245,269,'Rain ↓   Evaporation ↑',10)+T(20,289,'Invented units; runoff/recharge and use also matter',11)+T(20,321,'Rainfall alone is not safe usable supply.',12);c='Illustrative climate contrasts, not two actual regions. Rain adds water and evaporation transfers it to the atmosphere; quantities do not include every basin flow or demand.';}
 else if(v==='storage'){const stock=80-20*t;b=T(20,30,'SEASONAL STORAGE · TEACHING UNITS',13)+`<rect x="70" y="100" width="260" height="150" rx="6" fill="#2c4e63" stroke="#c5d5cb"/><rect x="70" y="${250-stock*1.5}" width="260" height="${stock*1.5}" fill="#9cbfc5"/>`+T(100,225,'Store: '+stock.toFixed(0),19)+flow(20,155,60,155,t)+flow(340,195,415,195,t,'#edb396')+flow(205,90,205,62,t,'#d8c9a4')+T(220,76,'Evaporation',10)+T(20,285,'Start80 + inflow20 − use35 − evaporation5',12)+T(20,319,'End60 units; playback restarts only the example',11);c='An invented storage balance. Inflow, withdrawal and evaporation occur over one period; simultaneous interpolation is explanatory, not measured rates or the full seasonal hydrograph.';}
 else if(v==='aquifer'){b=T(20,30,'MORE PUMPING THAN RECHARGE',14)+ground(t,35,10);c='Invented aquifer balance80+10−35=55. Pumping can improve immediate access while reducing future storage; the loop is not a real recharge or recovery forecast.';}
 else{b=T(20,30,'COMPARE THE SAME PLACE AND PERIOD',13)+B(20,70,400,'Usable supply60 units','After quality and environmental constraints')+B(20,180,400,'Demand80 units','Food / industry / household services')+flow(45,145,45,170,t)+T(20,294,'Supply − demand = −20 units',18)+T(20,327,'A deficit; no current real-world warning is implied',10);c='A defined illustrative usable-supply deficit. Environmental needs are already allowed for in the supply value, rather than silently assuming every natural flow can be abstracted.';}
 }
 if(k==='dev-water-supply-demand-change'){
 if(v==='history'){b=T(20,30,'1970s →2020s · CONCEPTUAL CHANGES',13)+B(20,70,400,'Demand pressures','Population / irrigation / cities / production')+B(20,165,400,'Human intervention','Storage / transfers / pumps / treatment')+B(20,260,400,'Some pressures can be reduced','Efficiency / reuse / changing industry');c='A mechanism timeline for roughly the past half-century, not a measured annual series. Different regions and sectors changed differently; demand growth is not an identical rate everywhere.';s='history';}
 else if(v==='interventions'){b=T(20,30,'STORAGE AND TRANSFER CHANGE ACCESS',13)+`<path d="M20 180Q95 210 175 180V278H20Z" fill="#9cbfc5"/><path d="M178 165V290" stroke="#e2d1b4" stroke-width="14"/>`+B(260,80,160,'Another catchment','Source and users')+B(260,245,160,'City / farms','Demand may grow')+flow(184,225,255,225,t)+L('M255 225V278')+D(255,225+53*t)+flow(184,225,184,315,t,'#edb396')+T(20,58,'Symbolic reservoir / dam',11)+T(20,333,'Donor flows, ecosystems, losses and cost matter',11);c='Illustrative stored water, downstream flow and transfer. Infrastructure redistributes availability through space and time; it does not manufacture new freshwater or guarantee that rising demand stays sustainable.';}
 else{const people=10+10*t;b=T(20,30,'FIXED SUPPLY · CONDITIONAL PRESSURE',13)+B(20,70,400,'Assumed supply100 teaching units','No change in quality / delivery assumed')+T(20,185,'Population: '+people.toFixed(0)+' people',19)+T(20,225,'Available per person: '+waterPerPerson(100,people).toFixed(1),19)+L('M20 270H420')+D(20+400*t,270)+T(20,319,'Illustration, not a population or water forecast',11);c='An invented fixed-supply example as population rises10→20. Per-person availability falls10→5, but actual future resources, use intensity, access and population are uncertain. Replay is not a real demographic reset.';}
 }
 if(k==='dev-water-sector-use'){
 if(v==='definitions'){b=T(20,30,'WITHDRAWAL IS A TRANSFER',14)+B(20,70,400,'Source → agriculture / industry / domestic','Water is taken from a river, lake or aquifer')+B(20,165,400,'Some is consumed or evaporates','For example crop transpiration')+B(20,260,400,'Some returns','Quantity, quality and timing may change');c='Static water-use accounting. Withdrawals and consumption differ; return flows can change quality and timing, and green rainwater used by crops is not identical to blue-water abstraction.';}
 else{b=T(20,30,'COMPARE AMOUNTS AS WELL AS SHARES',13)+B(20,75,400,'A: domestic share10% of1000 units','Volume100 units')+B(20,180,400,'B: domestic share20% of100 units','Volume20 units')+T(20,300,'Different denominators → different volumes',14)+T(20,328,'Invented teaching totals, not the country data',11);c='An invented comparison with different national totals. A higher percentage does not necessarily represent a larger withdrawal volume; the country chart supplies shares, not these volumes.';}
 }
 return F(b,c)+S(s);
}
